def _mode_of(dtype):
    if dtype.is_complex:
        raise RuntimeError("greater_ is not supported for complex tensors")
    if dtype.is_floating_point:
        return _MODE_F32
    return _MODE_I64


def _scalar_to_dtype(value, dtype):
    """Cast a python scalar the way PyTorch's wrapped-number promotion does."""
    if dtype.is_floating_point:
        try:
            return float(value), 0
        except OverflowError:
            return (float("inf") if value > 0 else -float("inf")), 0
    if dtype == torch.bool:
        return 0.0, 1 if value else 0
    info = torch.iinfo(dtype)
    mask = (1 << info.bits) - 1
    v = int(value) & mask
    if dtype.is_signed and v > (mask >> 1):
        v -= 1 << info.bits
    return 0.0, v


